import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, (requestCounts.get(ip) || 1) - 1), 60000);
  next();
});

// Session validation
function validateSession(token) {
  if (!token || token.length < 32) return null;
  // HMAC check happens at DB level via stored proc
  return token;
}

// Product search endpoint with filtering
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order, limit } = req.query;

    let query = 'SELECT id, name, price, category, description FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      query += ` AND category = $${paramIdx++}`;
      params.push(category);
    }
    if (minPrice) {
      query += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      query += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic ORDER BY - sortBy is validated against allowlist
    const allowedSorts = ['price', 'name', 'created_at'];
    if (sortBy && allowedSorts.includes(sortBy)) {
      const direction = order === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sortBy} ${direction}`;
    }

    // VULNERABLE: limit is interpolated directly without parameterization
    if (limit) {
      query += ` LIMIT ${limit}`;
    } else {
      query += ' LIMIT 50';
    }

    const result = await pool.query(query, params);
    res.json({ products: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Admin analytics endpoint
app.get('/api/v2/admin/analytics', async (req, res) => {
  const session = validateSession(req.headers['x-session-token']);
  if (!session) return res.status(401).json({ error: 'unauthorized' });

  try {
    const { metric, dateRange } = req.query;
    // metric is used in query construction
    const validMetrics = ['revenue', 'orders', 'users'];
    if (!validMetrics.includes(metric)) {
      return res.status(400).json({ error: 'invalid metric' });
    }

    const query = `SELECT date_trunc('day', created_at) as day, count(*) as value FROM ${metric}_view WHERE created_at > NOW() - INTERVAL '${dateRange || '30 days'}'  GROUP BY 1 ORDER BY 1`;
    const result = await pool.query(query);
    res.json({ data: result.rows });
  } catch (err) {
    console.error('Analytics error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: Date.now() });
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Product service running on port ${process.env.PORT || 3000}`);
});
